62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
69	     * domain containing at least one dot, with no whitespace in any part.
70	     */
71	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
72	
73	    /**
74	     * Common street-type abbreviations expanded during address normalization. Keys are the
75	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
76	     * expanded form it is replaced with.
77	     */
78	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
79	        "ST", "STREET",
80	        "RD", "ROAD",
81	        "AVE", "AVENUE");
82	
83	    private final ClinicService clinicService;
84	
85	    private final OwnerMapper ownerMapper;
86	
87	    private final PetMapper petMapper;
88	
89	    private final VisitMapper visitMapper;
90	
91	    public OwnerRestControllerV1(ClinicService clinicService,
92	                                 OwnerMapper ownerMapper,
93	                                 PetMapper petMapper,
94	                                 VisitMapper visitMapper) {
95	        this.clinicService = clinicService;
96	        this.ownerMapper = ownerMapper;
97	        this.petMapper = petMapper;
98	        this.visitMapper = visitMapper;
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
104	        Collection<Owner> owners;
105	        if (lastName != null) {
106	            owners = this.clinicService.findOwnerByLastName(lastName);
107	        } else {
108	            owners = this.clinicService.findAllOwners();
109	        }
110	        if (owners.isEmpty()) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
119	        Owner owner = this.clinicService.findOwnerById(ownerId);
120	        if (owner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        validateRequiredFields(ownerFieldsDto);
130	        HttpHeaders headers = new HttpHeaders();
131	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
132	        String address = normalizeAddress(ownerFieldsDto.getAddress());
133	        owner.setAddress(address);
134	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
135	            assignHousehold(owner, ownerFieldsDto.getLastName(), address);
136	        } else {
137	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), address);
138	        }
139	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
140	        rejectDuplicateTelephone(telephone);
141	        owner.setTelephone(telephone);
142	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
143	        if (owner.getRegistrationDate() == null) {
144	            owner.setRegistrationDate(LocalDate.now());
145	        }
146	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
147	        this.clinicService.saveOwner(owner);
148	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
149	        headers.setLocation(UriComponentsBuilder.newInstance()
150	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
151	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
157	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
158	        if (currentOwner == null) {
159	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
160	        }
161	        currentOwner.setAddress(ownerFieldsDto.getAddress());
162	        currentOwner.setCity(ownerFieldsDto.getCity());
163	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
164	        currentOwner.setLastName(ownerFieldsDto.getLastName());
165	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
166	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
167	        this.clinicService.saveOwner(currentOwner);
168	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Transactional
173	    @Override
174	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
175	        Owner owner = this.clinicService.findOwnerById(ownerId);
176	        if (owner == null) {
177	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
178	        }
179	        this.clinicService.deleteOwner(owner);
180	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
186	        Owner owner = this.clinicService.findOwnerById(ownerId);
187	        if (owner == null) {
188	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
189	        }
190	        HttpHeaders headers = new HttpHeaders();
191	        Pet pet = petMapper.toPet(petFieldsDto);
192	        owner.setId(ownerId);
193	        pet.setOwner(owner);
194	        pet.getType().setName(null);
195	        this.clinicService.savePet(pet);
196	        PetDto petDto = petMapper.toPetDto(pet);
197	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
198	            .buildAndExpand(pet.getId()).toUri());
199	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
200	    }
201	
202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Override
204	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
205	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
206	        if (currentOwner != null) {
207	            Pet currentPet = this.clinicService.findPetById(petId);
208	            if (currentPet != null) {
209	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
210	                currentPet.setName(petFieldsDto.getName());
211	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
212	                this.clinicService.savePet(currentPet);
213	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
214	            }
215	        }
216	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
217	    }
218	
219	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
220	    @Override
221	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
222	        HttpHeaders headers = new HttpHeaders();
223	        Visit visit = visitMapper.toVisit(visitFieldsDto);
224	        Pet pet = new Pet();
225	        pet.setId(petId);
226	        visit.setPet(pet);
227	        this.clinicService.saveVisit(visit);
228	        VisitDto visitDto = visitMapper.toVisitDto(visit);
229	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
230	            .buildAndExpand(visit.getId()).toUri());
231	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
232	    }
